def run(args):
    r = subprocess.run([sys.executable, T] + args, capture_output=True, text=True, encoding="utf-8")
    out = (r.stdout + r.stderr).strip()
    return r.returncode, out

if __name__ == "__main__":
    what = sys.argv[1] if len(sys.argv) > 1 else "all"
    if what in ("all", "sources"):
        for n, pub, title, off, d in SOURCES:
            code, out = run(["source", "--name", n, "--publisher", pub, "--title", title, "--official", off, "--page-date", d])
            print(code, n, out[-200:])
    if what in ("all", "facts"):
        for i, (n, claim, quote, d, st, ex) in enumerate(FACTS):
            a = ["add", "--prefix", "F", "--name", n, "--claim", claim, "--quote", quote, "--page-date", d, "--status", st]
            for k, v in ex.items():
                a += ["--" + k, v]
            code, out = run(a)
            print(i, code, out[-160:])
